import { strict as assert } from "node:assert";
import { test } from "node:test";
import { greet } from "./greet.mjs";

test("greets by name", () => {
  assert.equal(greet("world"), "hello world");
});

test("shouts when asked to", () => {
  assert.equal(greet("world", true), "HELLO WORLD");
});

